-- Ads people buy themselves: $5 for 1,000 impressions or $10 for 5,000, paid
-- through Stripe Checkout, reviewed by an admin before they go live, then served
-- in the same slots as the other ads until the bought impressions are used.
-- Served counts live in AdImpression like every ad's ("u:<id>" keys);
-- "impressionsServed" is the running total that stops the ad.
CREATE TABLE "SponsoredAd" (
  "id"                   integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "userId"               integer NOT NULL REFERENCES "User" ("id") ON DELETE CASCADE,
  "title"                varchar(60) NOT NULL,
  "body"                 varchar(140) NOT NULL DEFAULT '',
  "url"                  text NOT NULL CHECK (length("url") <= 2000 AND "url" ~* '^https://'),
  -- A blob name in the thumbs container (adimg/...), or null for the plain tile.
  "imageName"            varchar(200),
  "impressionsBought"    integer NOT NULL CHECK ("impressionsBought" IN (1000, 5000)),
  "priceCents"           integer NOT NULL CHECK ("priceCents" > 0),
  "impressionsServed"    integer NOT NULL DEFAULT 0,
  -- draft (not paid, or sent back), in_review (paid), active, paused, completed
  "status"               varchar(12) NOT NULL DEFAULT 'draft' CHECK ("status" IN ('draft', 'in_review', 'active', 'paused', 'completed')),
  "rejectionReason"      varchar(300),
  -- A rejection that Stripe could not refund by itself, for the admin to do by hand.
  "needsRefund"          boolean NOT NULL DEFAULT false,
  "stripeSessionId"      varchar(100),
  "stripePaymentIntent"  varchar(100),
  "paidDateTime"         timestamptz,
  "approvedDateTime"     timestamptz,
  "utcCreatedDateTime"   timestamptz NOT NULL DEFAULT now(),
  "utcUpdatedDateTime"   timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX "SponsoredAd_userId_idx" ON "SponsoredAd" ("userId");
CREATE INDEX "SponsoredAd_status_idx" ON "SponsoredAd" ("status");

